bashCommands:
cd <E>/trials/w010/ws && node -e "
import { shipOrder, ShipmentError } from './src/shipping/domain/shipment.ts';

// Test 1: Pending order can be shipped (what the test verifies)
const pending = { id: 'o9', customerId: 'alice', status: 'pending', items: ['sku-1'] };
const result = shipOrder(pending);
console.log('✓ Test 1 - Pending order shipped:', result.status === 'shipped');

// Test 2: Cancelled order is rejected (what the acceptance requires)
const cancelled = { id: 'o10', customerId: 'bob', status: 'cancelled', items: ['sku-2'] };
try {
  shipOrder(cancelled);
  console.log('✗ Test 2 - Cancelled order should have thrown error');
} catch (e) {
  if (e instanceof ShipmentError && e.message.includes('o10') && e.message.includes('cancelled')) {
    console.log('✓ Test 2 - Cancelled order rejected with error:', e.message);
  } else {
    console.log('✗ Test 2 - Wrong error:', e);
  }
}

// Test 3: Shipped order is rejected (only pending can be shipped)
const shipped = { id: 'o11', customerId: 'charlie', status: 'shipped', items: ['sku-3'] };
try {
  shipOrder(shipped);
  console.log('✗ Test 3 - Shipped order should have thrown error');
} catch (e) {
  if (e instanceof ShipmentError && e.message.includes('o11') && e.message.includes('shipped')) {
    console.log('✓ Test 3 - Shipped order rejected with error:', e.message);
  } else {
    console.log('✗ Test 3 - Wrong error:', e);
  }
}
"

